script:
$target = Join-Path $env:LOCALAPPDATA 'Microsoft\Windows\Explorer'
$removed = 0
foreach ($pattern in 'iconcache*','thumbcache*') {
  $files = Get-ChildItem -Path $target -Filter $pattern -Force -ErrorAction SilentlyContinue
  foreach ($file in $files) { Remove-Item -Path $file.FullName -Force -ErrorAction SilentlyContinue; $removed++ }
}
Write-Output ('已清理图标与缩略图缓存文件 ' + $removed + ' 个（正被占用的文件会在资源管理器重启后清除）。')

$target = {{Path}}
if (-not (Test-Path $target)) { Write-Error ('指定目录不存在：' + $target); exit 2 }
$items = Get-ChildItem -Path $target -Recurse -Force -ErrorAction SilentlyContinue
$size = ($items | Measure-Object -Property Length -Sum).Sum
if (-not $size) { $size = 0 }
Write-Output ('将清理 ' + $items.Count + ' 个对象，约 ' + [Math]::Round($size / 1MB, 1) + ' MB')
$items | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
Write-Output '已清空指定目录内容。'
